#include <ctype.h>
#include <stdio.h>
#include <string.h>

static int letter_counts[26];
static int words = 0;
static int characters = 0;
static int letters = 0;
static char longest[101] = "";
static size_t longest_length = 0;

static void handle_line(const char *line)
{
    size_t i = 0;
    while (line[i] != '\0') {
        unsigned char c = (unsigned char)line[i];
        if (c == '\n') {
            i++;
            continue;
        }
        if (isspace(c)) {
            characters++;
            i++;
            continue;
        }
        size_t start = i;
        while (line[i] != '\0' && !isspace((unsigned char)line[i])) {
            unsigned char w = (unsigned char)line[i];
            characters++;
            if (isalpha(w)) {
                letters++;
                letter_counts[tolower(w) - 'a']++;
            }
            i++;
        }
        words++;
        size_t length = i - start;
        if (length > longest_length && length <= 100) {
            longest_length = length;
            memcpy(longest, line + start, length);
            longest[length] = '\0';
        }
    }
}

static int best_letter(const int used[26])
{
    int best = -1;
    for (int i = 0; i < 26; i++) {
        if (used[i] || letter_counts[i] == 0) continue;
        if (best < 0 || letter_counts[i] > letter_counts[best]) best = i;
    }
    return best;
}

static void print_chart(void)
{
    int used[26] = {0};
    printf("Letters by count:\n");
    for (int shown = 0; shown < 4; shown++) {
        int letter = best_letter(used);
        if (letter < 0) break;
        used[letter] = 1;
        printf("%c %d ", 'a' + letter, letter_counts[letter]);
        for (int k = 0; k < letter_counts[letter]; k++) putchar('#');
        putchar('\n');
    }
}

int main(void)
{
    char line[1002];
    int lines = 0;
    while (fgets(line, sizeof line, stdin) != NULL) {
        lines++;
        handle_line(line);
    }
    printf("Lines: %d\n", lines);
    printf("Words: %d\n", words);
    printf("Characters: %d\n", characters);
    printf("Letters: %d\n", letters);
    if (words == 0) printf("Longest word: none\n");
    else printf("Longest word: %s (%zu)\n", longest, longest_length);
    int used[26] = {0};
    int top = best_letter(used);
    if (top < 0) {
        printf("Most common letter: none\n");
        return 0;
    }
    printf("Most common letter: %c (%d)\n", 'a' + top, letter_counts[top]);
    print_chart();
    return 0;
}
